DROP TABLE IF EXISTS `forecast_results`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `forecast_results` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL,
  `forecast_date` date NOT NULL,
  `forecasted_demand` int NOT NULL,
  `confidence_level` decimal(5,2) DEFAULT '0.95',
  `trend_indicator` enum('increasing','decreasing','stable') COLLATE utf8mb4_unicode_ci DEFAULT 'stable',
  `seasonality_factor` decimal(5,2) DEFAULT '1.00',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_product_forecast` (`product_id`,`forecast_date`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_forecast_date` (`forecast_date`),
  CONSTRAINT `forecast_results_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=47360 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

